/** Shared job types and request validation. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job representation returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A validated submission, with defaults applied. */
export interface JobInput {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export const MAX_INPUT_LENGTH = 1000;
export const DEFAULT_STEPS = 5;
export const MIN_STEPS = 1;
export const MAX_STEPS = 20;
export const MIN_FAIL_ATTEMPTS = 0;
export const MAX_FAIL_ATTEMPTS = 5;
export const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

export type ValidationResult = { ok: true; value: JobInput } | { ok: false; fields: FieldError[] };

function integerField(
  record: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number | undefined {
  if (!Object.hasOwn(record, name)) return fallback;
  const v = record[name];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
    return undefined;
  }
  return v;
}

/** Validates a parsed request body. Collects every offending field. */
export function validateSubmission(body: unknown): ValidationResult {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'Request body must be a JSON object.' }] };
  }
  const record = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(record)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  let input: string | undefined;
  if (!Object.hasOwn(record, 'input')) {
    fields.push({ field: 'input', message: 'Field is required.' });
  } else {
    const v = record.input;
    if (typeof v !== 'string') {
      fields.push({ field: 'input', message: 'Must be a string.' });
    } else if (v.length < 1 || v.length > MAX_INPUT_LENGTH) {
      fields.push({ field: 'input', message: `Must be 1 to ${MAX_INPUT_LENGTH} characters.` });
    } else if (v.trim() === '') {
      fields.push({ field: 'input', message: 'Must not be only whitespace.' });
    } else {
      input = v;
    }
  }

  const steps = integerField(record, 'steps', MIN_STEPS, MAX_STEPS, DEFAULT_STEPS, fields);
  const failAttempts = integerField(record, 'failAttempts', MIN_FAIL_ATTEMPTS, MAX_FAIL_ATTEMPTS, 0, fields);

  if (fields.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) {
    return { ok: false, fields };
  }
  return { ok: true, value: { input, steps, failAttempts } };
}

/** Returns a field error when the Idempotency-Key header is invalid, otherwise undefined. */
export function validateIdempotencyKey(value: string): FieldError | undefined {
  return KEY_PATTERN.test(value)
    ? undefined
    : { field: 'Idempotency-Key', message: 'Must be 1 to 128 characters: letters, digits, "_" or "-".' };
}

