import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';
import type { Job, JobInput, JobStatus } from './jobs.ts';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  idempotency_key TEXT UNIQUE,
  available_at INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  beat_at INTEGER NOT NULL
);
`;

/**
 * Opens the SQLite database shared by the server and worker processes and makes sure the schema
 * exists. Safe to call from either process at any time; existing data is never reset.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/** A row of the jobs table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  idempotency_key: string | null;
  available_at: number;
}

export function prepareStatements(db: DatabaseSync) {
  return {
    insert: db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error,
                         created_at, updated_at, idempotency_key, available_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, 0)`,
    ),
    byId: db.prepare('SELECT * FROM jobs WHERE id = ?'),
    byKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
    list: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
    selectRunning: db.prepare("SELECT * FROM jobs WHERE status = 'running' ORDER BY seq ASC LIMIT 1"),
    selectQueued: db.prepare(
      "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1",
    ),
    resetAttempt: db.prepare(
      "UPDATE jobs SET completed = 0, output = NULL, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
    ),
    claim: db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL,
              updated_at = ? WHERE id = ? AND status = 'queued'`,
    ),
    progress: db.prepare("UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'"),
    retry: db.prepare(
      `UPDATE jobs SET status = 'queued', completed = 0, output = NULL, error = NULL, available_at = ?, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ),
    fail: db.prepare(
      `UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = 'transient failure', updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ),
    complete: db.prepare(
      `UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ),
    beat: db.prepare(
      'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
    ),
    clearBeat: db.prepare('DELETE FROM worker_heartbeat WHERE id = 1'),
    heartbeat: db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1'),
  };
