  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the transaction may already be closed by SQLite
    }
    throw error;
  }
}

/** Serializes a stored row into the public job shape. */
export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export type SubmitResult = { kind: 'created'; job: Job } | { kind: 'replayed'; job: Job } | { kind: 'conflict' };

/**
 * Creates a job, or replays/conflicts with an existing job that used the same idempotency key.
 * The key lookup and insert happen in one IMMEDIATE transaction, so concurrent requests cannot
 * create duplicates.
 */
export function submitJob(db: DatabaseSync, q: Statements, input: JobInput, key: string | undefined): SubmitResult {
  return withTransaction<SubmitResult>(db, () => {
    if (key !== undefined) {
      const existing = q.byKey.get(key) as unknown as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === input.input &&
          existing.steps === input.steps &&
          existing.fail_attempts === input.failAttempts;
        return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    q.insert.run(id, input.input, input.steps, input.failAttempts, now, now, key ?? null);
    const row = q.byId.get(id) as unknown as JobRow;
    return { kind: 'created', job: toJob(row) };
  });
}

