import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, prepareStatements, withTransaction, type JobRow, type Statements } from './db.ts';
import type { DatabaseSync } from 'node:sqlite';

const STEP_MS = 100;
const IDLE_POLL_MS = 100;
const RETRY_DELAY_MS = 500;
const HEARTBEAT_MS = 500;
const MAX_ATTEMPTS = 3;

const db: DatabaseSync = openDatabase();
const q: Statements = prepareStatements(db);
let stopping = false;

function now(): string {
  return new Date().toISOString();
}

function beat(): void {
  try {
    q.beat.run(Date.now());
  } catch (error) {
    console.error('heartbeat failed:', error);
  }
}

/**
 * Picks the next attempt to run and records it durably. A job left `running` by a dead worker is
 * replayed with its persisted attempt number (no increment). Otherwise the oldest eligible queued
 * job is claimed, which increments `attempts`.
 */
function claimNext(): JobRow | undefined {
  return withTransaction(db, () => {
    const interrupted = q.selectRunning.get() as unknown as JobRow | undefined;
    if (interrupted) {
      q.resetAttempt.run(now(), interrupted.id);
      return { ...interrupted, completed: 0, output: null, error: null };
    }
    const queued = q.selectQueued.get(Date.now()) as unknown as JobRow | undefined;
    if (!queued) return undefined;
    q.claim.run(now(), queued.id);
    return q.byId.get(queued.id) as unknown as JobRow;
  });
}

/** Runs one attempt of a claimed job. Leaves the job `running` if asked to stop mid-attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress is recorded.
    await sleep(STEP_MS);
    if (stopping) return;
    withTransaction(db, () => {
      if (attempt < MAX_ATTEMPTS) q.retry.run(Date.now() + RETRY_DELAY_MS, now(), job.id);
      else q.fail.run(now(), job.id);
    });
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (step < job.steps) {
      q.progress.run(step, now(), job.id);
    } else {
      // Final step: progress and completion commit together.
      const output = job.input.toUpperCase();
      withTransaction(db, () => {
        q.progress.run(step, now(), job.id);
        q.complete.run(output, now(), job.id);
      });
    }
  }
}

async function main(): Promise<void> {
  console.log('worker started');
  while (!stopping) {
    try {
      const job = claimNext();
      if (!job) {
        await sleep(IDLE_POLL_MS);
        continue;
      }
      await runAttempt(job);
    } catch (error) {
      console.error('worker error:', error);
      await sleep(IDLE_POLL_MS);
    }
  }
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

await main();
clearInterval(heartbeatTimer);
try {
  q.clearBeat.run();
} catch (error) {
  console.error('clearing heartbeat failed:', error);
}
db.close();
console.log('worker stopped');

