import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase, prepareStatements, submitJob, toJob, type JobRow } from './db.ts';
import { validateIdempotencyKey, validateSubmission, type FieldError, type JobInput } from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;
const HEARTBEAT_FRESH_MS = 3000;
const SHUTDOWN_GRACE_MS = 2000;

const db = openDatabase();
const q = prepareStatements(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, headers);
}

type RouteName = 'root' | 'health' | 'jobs' | 'job';
interface Route {
  name: RouteName;
  methods: string[];
  id?: string;
}

function matchRoute(pathname: string): Route | undefined {
  if (pathname === '/') return { name: 'root', methods: ['GET'] };
  if (pathname === '/health') return { name: 'health', methods: ['GET'] };
  if (pathname === '/api/jobs') return { name: 'jobs', methods: ['GET', 'POST'] };
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      return undefined;
    }
    return { name: 'job', methods: ['GET'], id };
  }
  return undefined;
}

/** Reads the whole body. Resolves to null when it exceeds the size limit. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!tooLarge) chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function mediaType(header: string | undefined): string {
  return typeof header === 'string' ? header.split(';')[0]!.trim().toLowerCase() : '';
}

function workerUp(): boolean {
  const row = q.heartbeat.get() as unknown as { beat_at: number } | undefined;
  return row !== undefined && Date.now() - row.beat_at <= HEARTBEAT_FRESH_MS;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  let key: string | undefined;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    const keyError = validateIdempotencyKey(keyHeader);
    if (keyError) fields.push(keyError);
    else key = keyHeader;
  }

  const text = await readBody(req);
  let parsed: unknown;
  let parsedOk = false;
  if (mediaType(req.headers['content-type']) !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (text === null) {
    fields.push({ field: 'body', message: 'Request body is too large.' });
  } else {
    try {
      parsed = JSON.parse(text);
      parsedOk = true;
    } catch {
      fields.push({ field: 'body', message: 'Request body is not valid JSON.' });
    }
  }

  let value: JobInput | undefined;
  if (parsedOk) {
    const result = validateSubmission(parsed);
    if (result.ok) value = result.value;
    else fields.push(...result.fields);
  }

  if (fields.length > 0 || value === undefined) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
    return;
  }

  const outcome = submitJob(db, q, value, key);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const route = matchRoute(url.pathname);
  if (!route) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }
  const method = req.method ?? '';
  if (!route.methods.includes(method)) {
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed on this route.`, undefined, {
      allow: route.methods.join(', '),
    });
    return;
  }

  switch (route.name) {
    case 'root':
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(uiHtml);
      return;
    case 'health':
      sendJson(res, 200, { status: 'ok', worker: workerUp() ? 'up' : 'down' });
      return;
    case 'jobs':
      if (method === 'POST') return createJob(req, res);
      sendJson(res, 200, { jobs: (q.list.all() as unknown as JobRow[]).map(toJob) });
      return;
    case 'job': {
      const row = q.byId.get(route.id!) as unknown as JobRow | undefined;
      if (!row) sendError(res, 404, 'not_found', 'No such job.');
      else sendJson(res, 200, toJob(row));
      return;
    }
  }
}

const server = createServer((req, res) => {
  handle(req, res).catch((error: unknown) => {
    console.error('request failed:', error);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.on('error', (error) => {
  console.error('server error:', error);
  process.exitCode = 1;
  process.exit();
});
server.listen(port, () => console.log(`server listening on ${port}`));

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  // Stop accepting, let active responses finish, and drop idle keep-alive sockets. Anything still
  // open after the grace period is closed so the process exits promptly.
  server.close(() => db.close());
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

